from core.rules import RuleMachine


class EqualTopFrontierMerge:
    """Permite fusionar dos fronteras con la misma cima: mover la cima de una fuente ordenada o casi ordenada a un destino ordenado cuya cima tiene el mismo grupo."""

    name = "equal_top_frontier_merge"

    def __init__(self, max_source_slack=1, prefer_free_source=True):
        self.max_source_slack = int(max_source_slack)
        self.prefer_free_source = bool(prefer_free_source)

    def _is_frontier_source(self, partial, s):
        h = partial.h(s)
        if h <= 0:
            return False
        sorted_n = partial.sorted_n[s]
        return sorted_n >= h - self.max_source_slack

    def allowed(self, partial, memory, candidates):
        allowed = []
        for a in candidates:
            so = a.so
            sd = a.sd
            if so == sd:
                continue
            if partial.h(so) <= 0 or partial.e(sd) <= 0:
                continue
            if partial.h(sd) <= 0:
                continue
            if not self._is_frontier_source(partial, so):
                continue
            if not partial.is_sorted_stack(sd):
                continue
            if partial.g(so) != partial.g(sd):
                continue
            nxt = partial.after(so, sd)
            if partial.visited is not None and nxt in partial.visited:
                continue
            allowed.append(a)

        if allowed:
            allowed.sort(key=lambda a: self.score(partial, memory, a))
        return allowed

    def score(self, partial, memory, action):
        so = action.so
        sd = action.sd
        free_bonus = 0
        if self.prefer_free_source and partial.h(so) == 1:
            free_bonus = -1000
        elif self.prefer_free_source and partial.sorted_n[so] == partial.h(so) - 1:
            free_bonus = -100

        # Prefer consolidating into taller receivers and exhausting shorter sources.
        return (
            free_bonus,
            partial.h(so),
            -partial.h(sd),
            so,
            sd,
        )


def build_component(problem, **params):
    rule = EqualTopFrontierMerge(
        max_source_slack=params.get("max_source_slack", 1),
        prefer_free_source=params.get("prefer_free_source", True),
    )
    return RuleMachine(problem, [rule])
